"""Live OpenCitations smoke tests against the real APIs.

Each test sends one request; the whole module stays far below the documented
limit of 180 requests per minute. No credentials are needed.
"""

import pytest
from opcitato import OpcitatoSettings, OpcitatoSyncClient

pytestmark = pytest.mark.live_api

#: The operations of both APIs answer 200 with these example identifiers
#: (drawn from the official documentation examples on 2026-11-27).
CITED = "doi:10.1108/jd-12-2013-0166"
CITING = "doi:10.7717/peerj-cs.421"
OCI = "06101801781-06180334099"
VENUE = "issn:0138-9130"
PERSON = "orcid:0000-0002-8420-0696"


@pytest.fixture
def live_client():
    with OpcitatoSyncClient(settings=OpcitatoSettings(_env_file=None)) as client:
        yield client


def test_citations_smoke(live_client):
    rows = live_client.index.citations(CITED)
    assert rows
    row = rows[0]
    assert row.cited_identifiers[1].value == "10.1108/jd-12-2013-0166"
    assert row.journal_sc in {"yes", "no"}


def test_citations_csv_smoke(live_client):
    rows = live_client.index.citations(CITED, format="csv")
    assert [row.oci for row in rows]
    assert rows[0].citing


def test_references_smoke(live_client):
    rows = live_client.index.references(CITING)
    assert rows
    assert rows[0].citing_identifiers[1].scheme == "doi"


def test_citation_smoke(live_client):
    row = live_client.index.citation(OCI)
    assert row is not None
    assert row.oci == OCI


def test_counts_smoke(live_client):
    incoming = live_client.index.citation_count(CITED)
    outgoing = live_client.index.reference_count(CITING)
    venue = live_client.index.venue_citation_count(VENUE)
    assert isinstance(incoming, int) and incoming > 0
    assert isinstance(outgoing, int) and outgoing > 0
    assert isinstance(venue, int) and venue > incoming


def test_unknown_id_answers_empty_list_smoke(live_client):
    rows = live_client.index.citations("doi:10.9999/nonexistent.000")
    assert rows == []


def test_filter_and_sort_smoke(live_client):
    rows = live_client.index.citations(CITED, filter="creation:>2019-12")
    assert rows
    assert all(row.creation >= "2020" for row in rows)
    ordered = live_client.index.citations(CITED, sort="desc(creation)")
    assert ordered[0].creation >= ordered[-1].creation


def test_meta_metadata_smoke(live_client):
    rows = live_client.meta.metadata("doi:10.1007/978-1-4020-9632-7")
    assert rows[0].title == "Adaptive Environmental Management"
    assert rows[0].identifiers[0].scheme == "doi"


def test_meta_metadata_multi_id_smoke(live_client):
    rows = live_client.meta.metadata(
        ["doi:10.1108/jd-12-2013-0166", "doi:10.1016/j.websem.2012.08.001"]
    )
    assert len(rows) == 2
    ids = {row.identifiers[0].value for row in rows}
    assert ids == {"10.1108/jd-12-2013-0166", "10.1016/j.websem.2012.08.001"}


def test_meta_author_smoke(live_client):
    rows = live_client.meta.author(PERSON)
    assert rows
    assert any(PERSON in row.author for row in rows)
